/* From Uiverse.io by david-mohseni - Tags: loader */
.__UIV_SCOPE__ .loader {
  position: relative;
  width: 54px;
  height: 54px;
  border-radius: 10px;
}

.__UIV_SCOPE__ .loader div {
  width: 8%;
  height: 24%;
  background: rgb(128, 128, 128);
  position: absolute;
  left: 50%;
  top: 30%;
  opacity: 0;
  border-radius: 50px;
  box-shadow: 0 0 3px rgba(0,0,0,0.2);
  animation: fade458 1s linear infinite;
}

@keyframes fade458 {
  from {
    opacity: 1;
  }

  to {
    opacity: 0.25;
  }
}

.__UIV_SCOPE__ .loader .bar1 {
  transform: rotate(0deg) translate(0, -130%);
  animation-delay: 0s;
}

.__UIV_SCOPE__ .loader .bar2 {
  transform: rotate(30deg) translate(0, -130%);
  animation-delay: -1.1s;
}

.__UIV_SCOPE__ .loader .bar3 {
  transform: rotate(60deg) translate(0, -130%);
  animation-delay: -1s;
}

.__UIV_SCOPE__ .loader .bar4 {
  transform: rotate(90deg) translate(0, -130%);
  animation-delay: -0.9s;
}

.__UIV_SCOPE__ .loader .bar5 {
